-- Fixed classifier catalog. Preserve legacy/custom categories and their references.
ALTER TABLE transactions ADD COLUMN classification TEXT CHECK (classification IS NULL OR json_valid(classification));
CREATE TABLE planning_category_groups (id TEXT PRIMARY KEY NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
INSERT INTO planning_category_groups(id,data)
SELECT replace(json_extract(c.value,'$.id'),'SPACE',s.id), replace(c.value,'SPACE',s.id)
FROM planning_spaces s, json_each('[{"color":"#64748b","icon":"home","id":"SPACE:group:casa","name":"Casa","spaceId":"SPACE"},{"color":"#0891b2","icon":"shopping","id":"SPACE:group:cotidiano","name":"Cotidiano","spaceId":"SPACE"},{"color":"#d97706","icon":"utensils","id":"SPACE:group:alimentacao","name":"Alimentação","spaceId":"SPACE"},{"color":"#2563eb","icon":"car","id":"SPACE:group:transporte","name":"Transporte","spaceId":"SPACE"},{"color":"#db2777","icon":"heart","id":"SPACE:group:bem-estar","name":"Saúde e bem-estar","spaceId":"SPACE"},{"color":"#7c3aed","icon":"book","id":"SPACE:group:educacao","name":"Educação","spaceId":"SPACE"},{"color":"#059669","icon":"star","id":"SPACE:group:lazer","name":"Lazer","spaceId":"SPACE"},{"color":"#be123c","icon":"gift","id":"SPACE:group:compromissos","name":"Compromissos","spaceId":"SPACE"},{"color":"#475569","icon":"money","id":"SPACE:group:financas","name":"Finanças","spaceId":"SPACE"}]') c;
INSERT OR IGNORE INTO planning_categories(id,data)
SELECT replace(json_extract(c.value,'$.id'),'SPACE',s.id), replace(c.value,'SPACE',s.id)
FROM planning_spaces s, json_each('[{"color":"#db2777","groupId":"SPACE:group:bem-estar","hidden":false,"icon":"activity","id":"SPACE:fixed:academia","kind":"expense","limitMinor":null,"name":"Academia","spaceId":"SPACE","system":true},{"color":"#64748b","groupId":"SPACE:group:casa","hidden":false,"icon":"home","id":"SPACE:fixed:aluguel","kind":"expense","limitMinor":null,"name":"Aluguel","spaceId":"SPACE","system":true},{"color":"#059669","groupId":"SPACE:group:lazer","hidden":false,"icon":"star","id":"SPACE:fixed:assinaturas","kind":"expense","limitMinor":null,"name":"Assinaturas","spaceId":"SPACE","system":true},{"color":"#64748b","groupId":"SPACE:group:casa","hidden":false,"icon":"home","id":"SPACE:fixed:casa","kind":"expense","limitMinor":null,"name":"Casa","spaceId":"SPACE","system":true},{"color":"#be123c","groupId":"SPACE:group:compromissos","hidden":false,"icon":"heart","id":"SPACE:fixed:casamento","kind":"expense","limitMinor":null,"name":"Casamento","spaceId":"SPACE","system":true},{"color":"#2563eb","groupId":"SPACE:group:transporte","hidden":false,"icon":"car","id":"SPACE:fixed:combustivel","kind":"expense","limitMinor":null,"name":"Combustível","spaceId":"SPACE","system":true},{"color":"#0891b2","groupId":"SPACE:group:cotidiano","hidden":false,"icon":"shopping","id":"SPACE:fixed:compras","kind":"expense","limitMinor":null,"name":"Compras","spaceId":"SPACE","system":true},{"color":"#2563eb","groupId":"SPACE:group:transporte","hidden":false,"icon":"car","id":"SPACE:fixed:corridas","kind":"expense","limitMinor":null,"name":"Corridas","spaceId":"SPACE","system":true},{"color":"#db2777","groupId":"SPACE:group:bem-estar","hidden":false,"icon":"heart","id":"SPACE:fixed:cuidados-pessoais","kind":"expense","limitMinor":null,"name":"Cuidados Pessoais","spaceId":"SPACE","system":true},{"color":"#7c3aed","groupId":"SPACE:group:educacao","hidden":false,"icon":"book","id":"SPACE:fixed:cursos","kind":"expense","limitMinor":null,"name":"Cursos","spaceId":"SPACE","system":true},{"color":"#be123c","groupId":"SPACE:group:compromissos","hidden":false,"icon":"gift","id":"SPACE:fixed:doacoes","kind":"expense","limitMinor":null,"name":"Doações","spaceId":"SPACE","system":true},{"color":"#7c3aed","groupId":"SPACE:group:educacao","hidden":false,"icon":"book","id":"SPACE:fixed:educacao-geral","kind":"expense","limitMinor":null,"name":"Educação Geral","spaceId":"SPACE","system":true},{"color":"#64748b","groupId":"SPACE:group:casa","hidden":false,"icon":"home","id":"SPACE:fixed:energia","kind":"expense","limitMinor":null,"name":"Energia","spaceId":"SPACE","system":true},{"color":"#2563eb","groupId":"SPACE:group:transporte","hidden":false,"icon":"car","id":"SPACE:fixed:estacionamento-pedagio","kind":"expense","limitMinor":null,"name":"Estacionamento e Pedágio","spaceId":"SPACE","system":true},{"color":"#7c3aed","groupId":"SPACE:group:educacao","hidden":false,"icon":"book","id":"SPACE:fixed:faculdade","kind":"expense","limitMinor":null,"name":"Faculdade","spaceId":"SPACE","system":true},{"color":"#db2777","groupId":"SPACE:group:bem-estar","hidden":false,"icon":"heart","id":"SPACE:fixed:farmacia","kind":"expense","limitMinor":null,"name":"Farmácia","spaceId":"SPACE","system":true},{"color":"#475569","groupId":"SPACE:group:financas","hidden":false,"icon":"money","id":"SPACE:fixed:financiamento","kind":"expense","limitMinor":null,"name":"Financiamento","spaceId":"SPACE","system":true},{"color":"#64748b","groupId":"SPACE:group:casa","hidden":false,"icon":"home","id":"SPACE:fixed:gas","kind":"expense","limitMinor":null,"name":"Gás","spaceId":"SPACE","system":true},{"color":"#475569","groupId":"SPACE:group:financas","hidden":false,"icon":"money","id":"SPACE:fixed:impostos-taxas","kind":"expense","limitMinor":null,"name":"Impostos e Taxas","spaceId":"SPACE","system":true},{"color":"#64748b","groupId":"SPACE:group:casa","hidden":false,"icon":"home","id":"SPACE:fixed:internet","kind":"expense","limitMinor":null,"name":"Internet","spaceId":"SPACE","system":true},{"color":"#475569","groupId":"SPACE:group:financas","hidden":false,"icon":"money","id":"SPACE:fixed:investimentos","kind":"transfer","limitMinor":null,"name":"Investimentos","spaceId":"SPACE","system":true},{"color":"#d97706","groupId":"SPACE:group:alimentacao","hidden":false,"icon":"utensils","id":"SPACE:fixed:lanches","kind":"expense","limitMinor":null,"name":"Lanches","spaceId":"SPACE","system":true},{"color":"#0891b2","groupId":"SPACE:group:cotidiano","hidden":false,"icon":"home","id":"SPACE:fixed:lavanderia","kind":"expense","limitMinor":null,"name":"Lavanderia","spaceId":"SPACE","system":true},{"color":"#059669","groupId":"SPACE:group:lazer","hidden":false,"icon":"star","id":"SPACE:fixed:lazer","kind":"expense","limitMinor":null,"name":"Lazer","spaceId":"SPACE","system":true},{"color":"#0891b2","groupId":"SPACE:group:cotidiano","hidden":false,"icon":"home","id":"SPACE:fixed:manutencao","kind":"expense","limitMinor":null,"name":"Manutenção","spaceId":"SPACE","system":true},{"color":"#d97706","groupId":"SPACE:group:alimentacao","hidden":false,"icon":"shopping","id":"SPACE:fixed:mercado","kind":"expense","limitMinor":null,"name":"Mercado","spaceId":"SPACE","system":true},{"color":"#db2777","groupId":"SPACE:group:bem-estar","hidden":false,"icon":"heart","id":"SPACE:fixed:odontologia","kind":"expense","limitMinor":null,"name":"Odontologia","spaceId":"SPACE","system":true},{"color":"#0891b2","groupId":"SPACE:group:cotidiano","hidden":false,"icon":"heart","id":"SPACE:fixed:petshop","kind":"expense","limitMinor":null,"name":"Petshop","spaceId":"SPACE","system":true},{"color":"#d97706","groupId":"SPACE:group:alimentacao","hidden":false,"icon":"utensils","id":"SPACE:fixed:restaurantes","kind":"expense","limitMinor":null,"name":"Restaurantes","spaceId":"SPACE","system":true},{"color":"#475569","groupId":"SPACE:group:financas","hidden":false,"icon":"briefcase","id":"SPACE:fixed:salario-renda","kind":"income","limitMinor":null,"name":"Salário e Renda","spaceId":"SPACE","system":true},{"color":"#db2777","groupId":"SPACE:group:bem-estar","hidden":false,"icon":"heart","id":"SPACE:fixed:saude-geral","kind":"expense","limitMinor":null,"name":"Saúde Geral","spaceId":"SPACE","system":true},{"color":"#be123c","groupId":"SPACE:group:compromissos","hidden":false,"icon":"heart","id":"SPACE:fixed:seguro","kind":"expense","limitMinor":null,"name":"Seguro","spaceId":"SPACE","system":true},{"color":"#475569","groupId":"SPACE:group:financas","hidden":false,"icon":"transfer","id":"SPACE:transfer","kind":"transfer","limitMinor":null,"name":"Transferências","spaceId":"SPACE","system":true}]') c;
UPDATE planning_categories SET data=json_set(data,
'$.name','Transferências','$.color','#475569','$.icon','transfer','$.groupId',json_extract(data,'$.spaceId')||':group:financas')
WHERE id=json_extract(data,'$.spaceId')||':transfer' AND json_extract(data,'$.system')=1;
UPDATE planning_categories SET data=json_set(data,'$.hidden',json('true'))
WHERE id IN (json_extract(data,'$.spaceId')||':income',json_extract(data,'$.spaceId')||':expense') AND json_extract(data,'$.system')=1;
UPDATE planning_categories SET data=json_set(data,
'$.color',coalesce(json_extract(data,'$.color'),'#64748b'),
'$.icon',coalesce(json_extract(data,'$.icon'),'shopping'),
'$.groupId',json_extract(data,'$.groupId'));
